{"ts":"2026-09-20T00:35:25.312+03:00","v":"1","level":"DEBUG","logger":"org.hibernate.SQL","thread":"Test worker","msg":"SELECT a.*\nFROM assignments a\nJOIN semesters existing_semester ON existing_semester.id = a.semester_id\nWHERE a.teacher_id = ?\n  AND a.subject_id = ?\n  AND a.group_id = ?\n  AND a.semester_id = ?\n  AND a.lesson_type = CAST(? AS subject_type)\n  AND daterange(\n        a.valid_from,\n        COALESCE(a.valid_until_exclusive, existing_semester.date_to + 1),\n        '[)'\n      ) && daterange(\n        CAST(? AS date),\n        COALESCE(CAST(? AS date), existing_semester.date_to + 1),\n        '[)'\n      )\nLIMIT 1\n","traceId":"bac2534a28d448f5976f589a8e4af14f","service":"academic-service"}
